 'C_growth': (lambda p,e,t: -(p[0]*e*np.exp(p[1]*e*t**p[2]) + p[3]*e**p[4]*t**p[5]), 6),
 'D_quad_exp': (lambda p,e,t: -e*(p[0]+p[1]*t+p[2]*e)*np.exp(p[3]*e*t**p[4]), 5),
 'E_sat': (lambda p,e,t: -(p[0]*e**p[1]*(1-np.exp(-p[2]*e*t**p[3]))*t**p[4] + p[5]*e*t**p[6]), 7),
}
